                    writeFrame(H2_WINDOW_UPDATE, 0, 0, wu.toByteArray())
                    val wu2 = ByteArrayOutputStream()
                    writeWindowUpdate(wu2, body.size)
                    writeFrame(H2_WINDOW_UPDATE, 0, streamId, wu2.toByteArray())
                    val buf = dataBuffers.getOrPut(streamId) { ByteArrayOutputStream() }
                    buf.write(body, 0, body.size)
                    drainMessages(streamId)
                }
                if ((flags and FLAG_END_STREAM) != 0) {
                    emitTrailersFrame(streamId, 2, "missing grpc-status", null)
                }
            }
            else -> {
                // GOAWAY and unknown frames: nothing to do.
            }
        }
        return true
    }

    private fun writeWindowUpdate(out: ByteArrayOutputStream, increment: Int) {
        out.write((increment shr 24) and 0x7f)
        out.write((increment shr 16) and 0xff)
        out.write((increment shr 8) and 0xff)
        out.write(increment and 0xff)
    }

    private fun onHeaders(streamId: Long, endStream: Boolean, block: ByteArray) {
        val headers = decoder.decode(block)
        val metadata = LinkedHashMap<String, String>()
        var status: String? = null
        var message: String? = null
        for (h in headers) {
            val name = h[0]
            val value = h[1]
            when {
                name == "grpc-status" -> status = value
                name == "grpc-message" -> message = value
                name == "grpc-encoding" -> {
                    if (value == "gzip") decompressIn.add(streamId)
                }
                name.startsWith(":") || name == "content-type" || name == "grpc-accept-encoding" -> {
                    // transport-owned: not metadata
                }
                else -> metadata.putIfAbsent(name, value)
            }
        }
        val first = headersSeen.add(streamId)
        if (endStream && status != null) {
            emitTrailersFrame(streamId, status.toLong(), percentDecode(message ?: ""), metadata)
        } else if (first) {
            emitHeadersFrame(streamId, metadata)
            if (endStream) {
                emitTrailersFrame(streamId, 2, "missing grpc-status", metadata)
            }
        } else if (endStream) {
            emitTrailersFrame(streamId, 2, "missing grpc-status", metadata)
        }
    }

    private fun drainMessages(streamId: Long) {
        val buf = dataBuffers[streamId] ?: return
        val data = buf.toByteArray()
        var off = 0
        while (data.size - off >= 5) {
            val mlen = ((data[off + 1].toInt() and 0xff).toLong() shl 24) or ((data[off + 2].toInt() and 0xff).toLong() shl 16) or
                ((data[off + 3].toInt() and 0xff).toLong() shl 8) or (data[off + 4].toInt() and 0xff).toLong()
            if (data.size - off - 5 < mlen) break
            val compressed = data[off].toInt() and 0xff
            var message = data.copyOfRange(off + 5, off + 5 + mlen.toInt())
            off += 5 + mlen.toInt()
            if (compressed == 1 || decompressIn.contains(streamId)) {
                message = gunzip(message)
            }
            emit(Wire.FRAME_DATA.toLong(), streamId, message)
        }
        buf.reset()
        buf.write(data, off, data.size - off)
    }

    override fun send(message: ByteArray) {
        if (message.size < 9) throw IOException("short frame")
        val type = message[0].toInt() and 0xff
        val streamId = ((message[1].toInt() and 0xff).toLong() shl 24) or ((message[2].toInt() and 0xff).toLong() shl 16) or
            ((message[3].toInt() and 0xff).toLong() shl 8) or (message[4].toInt() and 0xff).toLong()
        val flen = ((message[5].toInt() and 0xff) shl 24) or ((message[6].toInt() and 0xff) shl 16) or
            ((message[7].toInt() and 0xff) shl 8) or (message[8].toInt() and 0xff)
        val payload = message.copyOfRange(9, 9 + flen)
        when (type) {
            Wire.FRAME_HEADERS -> {
                val body = Codec.parseJsonObject(String(payload, StandardCharsets.UTF_8))
                val path = body["path"] as? String ?: ""
                val metadata = LinkedHashMap<String, String>()
                val md = body["metadata"]
                if (md is Map<*, *>) {
                    for ((key, value) in md) {
                        metadata[key.toString()] = value.toString()
                    }
                }
                synchronized(cond) {
                    streamWindows.putIfAbsent(streamId, peerInitialWindow)
                }
                if (metadata["grpc-encoding"] == "gzip") {
                    compressOut[streamId] = true
                }
                val block = ByteArrayOutputStream()
                block.write(0x83) // :method: POST
                block.write(if (scheme == "https") 0x87 else 0x86) // :scheme
                writeLiteralIndexedName(block, 4, path) // :path
                writeLiteralIndexedName(block, 1, authority) // :authority
                writeLiteralIndexedName(block, 31, "application/grpc") // content-type
                writeLiteralNewName(block, "grpc-accept-encoding", "gzip,identity")
                writeLiteralNewName(block, "te", "trailers")
                for ((key, value) in metadata) {
                    val k = key.lowercase()
                    if (k == "grpc-encoding") {
                        writeLiteralNewName(block, k, "gzip")
                    } else {
                        writeLiteralNewName(block, k, value)
                    }
                }
                writeFrame(H2_HEADERS, FLAG_END_HEADERS, streamId, block.toByteArray())
            }
            Wire.FRAME_DATA -> {
                val compressed = compressOut[streamId] == true
                var body = payload
                if (compressed) body = gzip(payload)
                val wire = ByteArray(5 + body.size)
                wire[0] = (if (compressed) 1 else 0).toByte()
                wire[1] = (body.size shr 24).toByte()
                wire[2] = (body.size shr 16).toByte()
                wire[3] = (body.size shr 8).toByte()
                wire[4] = body.size.toByte()
                body.copyInto(wire, 5)
                var sent = 0
                while (sent < wire.size) {
                    var allowance = 0
                    synchronized(cond) {
                        while (!closed && (connWindow <= 0 ||
                                (streamWindows[streamId] ?: peerInitialWindow) <= 0)) {
                            cond.wait()
                        }
                        if (closed) throw IOException("transport closed")
                        val sw = streamWindows[streamId] ?: peerInitialWindow
                        allowance = minOf(minOf(connWindow, sw),
                            minOf(MAX_FRAME_PAYLOAD.toLong(), (wire.size - sent).toLong())).toInt()
                        connWindow -= allowance
                        streamWindows[streamId] = sw - allowance
                    }
                    writeFrame(H2_DATA, 0, streamId, wire.copyOfRange(sent, sent + allowance))
                    sent += allowance
                }
            }
            Wire.FRAME_HALF_CLOSE -> writeFrame(H2_DATA, FLAG_END_STREAM, streamId, ByteArray(0))
            Wire.FRAME_RST -> writeFrame(H2_RST_STREAM, 0, streamId, byteArrayOf(0, 0, 0, 8))
            else -> {
                // Trailers never travel client -> server here.
            }
        }
    }

    override fun recv(): ByteArray {
        val msg = queue.take()
        if (msg === CLOSED_MARK) {
            queue.offer(CLOSED_MARK)
            throw EOFException("transport closed")
        }
        return msg
    }

    override fun close() {
        try {
            socket.close()
        } catch (e: IOException) {
            // already closed
        }
    }

}
